<script>
  function getmobileappmsg(domainname){

        var countrycode = $('#countrycode :selected').val();
        var mobileno = $('#mobileno').val();

        $("#err_mobile").html("");

        if(mobileno != "" && numericsonly(mobileno))   {

            if((countrycode == "91" && mobileno.length != 10) || (countrycode != "91" && mobileno.length < 10))   {

                $("#err_mobile").attr("class","errortxt");
                $("#err_mobile").html("Please enter a valid mobile number");
            } else {

                var param = "countrycode="+countrycode+"&mobileno="+mobileno;

                $.ajax({ 
                    url:"/login/mobileappsms.php",
                    type: "POST",
                    data: param,
                    success: function (response){

                        $.colorbox({
                            html : "<div style='padding:5px 40px 15px 20px; line-height : 18px;'>"+response+"</div>"
                        });

                        $("#mobileno").val("");
                        $('#countrycode option[value="91"]').attr('selected', 'selected');
                    }
                });
            }
        } else {
            $("#err_mobile").attr("class","errortxt");
            $("#err_mobile").html("Please enter a valid mobile number");
            $("#mobileno").val("");
        }
    }

    function numericsonly(value)   {

        var invalidChars = /[^0-9]/gi
        if(invalidChars.test(value))    {
            return false;
        }
        else
            return true;
    }

</script>
